expand_details.cypher:
MATCH (start:service {name: 'ts-news-service'})
CALL apoc.path.expandConfig(start, {
    sequence: 'service,targets,pod,hosts,node',
    minLevel: 0,
    maxLevel: 2,
    bfs: true
})
YIELD path
RETURN path, length(path) AS hops
ORDER BY hops;

MATCH (start:service {name: 'ts-news-service'})
CALL apoc.path.expandConfig(start, {
    sequence: 'service,targets,pod,hosts,node,hosts,pod,contains,container,manages,disk device',
    minLevel: 0,
    maxLevel: 5,
    bfs: true
})
YIELD path
RETURN path, length(path) AS hops
ORDER BY hops;
